function plot_performance_results()
% Plot summarized performance results generated by extract_performance_results.ps1.

rootDir = fileparts(fileparts(mfilename('fullpath')));
tablesDir = fullfile(rootDir, 'tables');
figuresDir = fullfile(rootDir, 'figures');
if ~exist(figuresDir, 'dir')
    mkdir(figuresDir);
end

plotYoloTraining(tablesDir, figuresDir);
plotRoundtrip(tablesDir, figuresDir);
plotLinkAndDecoder(tablesDir, figuresDir);
end

function plotYoloTraining(tablesDir, figuresDir)
yoloFile = fullfile(tablesDir, 'yolo_training_summary.csv');
if ~isfile(yoloFile)
    return;
end
T = readtable(yoloFile, 'TextType', 'string', 'VariableNamingRule', 'preserve');
if isempty(T)
    return;
end
taskLabels = categorical(composeShortLabels(T.task, strings(height(T), 1)));

fig = figure('Visible', 'off', 'Color', 'w', 'Position', [100 100 980 560]);
tiledlayout(1, 2, 'Padding', 'compact', 'TileSpacing', 'compact');

nexttile;
barh(taskLabels, [T.best_map50, T.best_map50_95]);
grid on;
xlabel('Score');
xlim([0 1]);
title('YOLO detection metrics');
legend({'Best mAP50', 'Best mAP50-95'}, 'Location', 'southoutside', 'Orientation', 'horizontal');

nexttile;
barh(taskLabels, [T.final_precision, T.final_recall]);
grid on;
xlabel('Score');
xlim([0 1]);
title('Final precision and recall');
legend({'Precision', 'Recall'}, 'Location', 'southoutside', 'Orientation', 'horizontal');

exportgraphics(fig, fullfile(figuresDir, 'yolo_training_performance.png'), 'Resolution', 200);
close(fig);
end

function plotRoundtrip(tablesDir, figuresDir)
rtFile = fullfile(tablesDir, 'gpu_direct_roundtrip_summary.csv');
if ~isfile(rtFile)
    return;
end
T = readtable(rtFile, 'TextType', 'string', 'VariableNamingRule', 'preserve');
if isempty(T)
    return;
end
labels = categorical(composeShortLabels(T.task, T.scheme));

fig = figure('Visible', 'off', 'Color', 'w', 'Position', [100 100 1100 620]);
tiledlayout(1, 2, 'Padding', 'compact', 'TileSpacing', 'compact');

nexttile;
barh(labels, T.fps);
grid on;
xlabel('FPS');
title('GPU direct roundtrip throughput');

nexttile;
barh(labels, T.avg_payload_kb);
grid on;
xlabel('KB/frame');
title('Average payload size');

exportgraphics(fig, fullfile(figuresDir, 'gpu_direct_roundtrip_performance.png'), 'Resolution', 200);
close(fig);
end

function labels = composeShortLabels(task, scheme)
labels = strings(numel(task), 1);
for i = 1:numel(task)
    t = lower(string(task(i)));
    s = lower(string(scheme(i)));
    if contains(t, "viso")
        base = "VISO";
    elseif contains(t, "earthquake")
        base = "Earthquake";
    elseif contains(t, "maritime")
        base = "Ship";
    elseif contains(t, "flood")
        base = "Flood";
    else
        base = string(task(i));
    end

    if strlength(s) > 0
        if contains(s, "roi")
            suffix = "ROI";
        elseif contains(s, "uniform")
            suffix = "Uniform";
        else
            suffix = string(scheme(i));
        end
        labels(i) = base + " " + suffix;
    else
        labels(i) = base;
    end
end
end

function plotLinkAndDecoder(tablesDir, figuresDir)
linkFile = fullfile(tablesDir, 'usrp_link_summary.csv');
awgnFile = fullfile(tablesDir, 'decoder_awgn_summary.csv');
hasLink = isfile(linkFile);
hasAwgn = isfile(awgnFile);
if ~hasLink && ~hasAwgn
    return;
end

fig = figure('Visible', 'off', 'Color', 'w', 'Position', [100 100 980 540]);
tiledlayout(1, 2, 'Padding', 'compact', 'TileSpacing', 'compact');

nexttile;
if hasLink
    L = readtable(linkFile, 'TextType', 'string', 'VariableNamingRule', 'preserve');
    vals = [L.goodput_mbps, L.fps, L.decode_total_ms_per_frame];
    bar(vals);
    set(gca, 'XTickLabel', {'Goodput Mbps', 'FPS', 'Decode ms/frame'});
    grid on;
    title('USRP link summary');
else
    axis off;
    text(0.1, 0.5, 'No USRP link data');
end

nexttile;
if hasAwgn
    A = readtable(awgnFile, 'TextType', 'string', 'VariableNamingRule', 'preserve');
    yyaxis left;
    semilogy(A.snr_db, A.ber, 'o-', 'LineWidth', 1.5);
    ylabel('BER');
    yyaxis right;
    semilogy(A.snr_db, A.fer, 's-', 'LineWidth', 1.5);
    ylabel('FER');
    grid on;
    xlabel('SNR (dB)');
    title('Decoder AWGN result');
else
    axis off;
    text(0.1, 0.5, 'No AWGN data');
end

exportgraphics(fig, fullfile(figuresDir, 'link_decoder_performance.png'), 'Resolution', 200);
close(fig);
end
